Lemma bufcredA_push : forall cr cap kx bx need, PMSA.bufcredA L cr cap kx bx -> 24 <= cap -> cap mod 8 = 0 -> cap <= need -> need < 2 ^ 26 ->
  let c := PML.grow_cap cap need in
